package net.kaaass.zerotierfix.util;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import org.junit.Test;

import java.io.ByteArrayOutputStream;
import java.util.Arrays;

/**
 * Tests for the planet file parser.
 *
 * <p>ZeroTier 1.12 and 1.16 share the same world layout (64 byte key set + 96 byte signature), so
 * the parser accepts planet files generated by either version and only rejects structurally
 * invalid files.
 */
public class PlanetFileTest {

    private static byte[] uint64(long value) {
        byte[] out = new byte[8];
        for (int i = 7; i >= 0; i--) {
            out[i] = (byte) (value & 0xff);
            value >>>= 8;
        }
        return out;
    }

    private static byte[] identity() {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        out.writeBytes(new byte[]{0x01, 0x02, 0x03, 0x04, 0x05});
        out.write(0); // identity type
        byte[] publicKey = new byte[64];
        Arrays.fill(publicKey, (byte) 0x11);
        out.writeBytes(publicKey);
        out.write(0); // private key length
        return out.toByteArray();
    }

    private static byte[] planet(long id, long timestamp, int roots) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        out.write(PlanetFile.TYPE_PLANET);
        out.writeBytes(uint64(id));
        out.writeBytes(uint64(timestamp));
        byte[] key = new byte[64];
        Arrays.fill(key, (byte) 0x22);
        out.writeBytes(key);
        byte[] signature = new byte[96];
        Arrays.fill(signature, (byte) 0x33);
        out.writeBytes(signature);
        out.write(roots);
        for (int i = 0; i < roots; i++) {
            out.writeBytes(identity());
            out.write(1); // one stable endpoint
            out.write(4); // IPv4
            out.writeBytes(new byte[]{10, 0, 0, (byte) (1 + i)});
            out.writeBytes(new byte[]{0x27, 0x0f}); // port 9999
        }
        return out.toByteArray();
    }

    @Test
    public void parsesPlanet() throws Exception {
        PlanetFile planet = PlanetFile.parse(planet(0x0123456789abcdefL, 123456789L, 2));
        assertEquals("0123456789abcdef", planet.getIdString());
        assertEquals(123456789L, planet.getTimestamp());
        assertEquals(Arrays.asList("0102030405", "0102030405"), planet.getRootAddresses());
    }

    @Test
    public void rejectsTruncatedFile() {
        try {
            PlanetFile.parse(new byte[]{1, 2, 3});
            fail("truncated planet accepted");
        } catch (PlanetFile.FormatException expected) {
            assertTrue(expected.getMessage().contains("too short"));
        }
    }

    @Test
    public void rejectsUnsupportedKeyLayout() throws Exception {
        // Layout with a 32 byte key and 64 byte signature, which is not a ZeroTier 1.12+ world.
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        out.write(PlanetFile.TYPE_PLANET);
        out.writeBytes(uint64(0x0123456789abcdefL));
        out.writeBytes(uint64(1));
        out.writeBytes(new byte[32]);
        out.writeBytes(new byte[64]);
        out.write(1);
        out.writeBytes(new byte[]{1, 2, 3, 4, 5, 0});
        out.writeBytes(new byte[64]);
        out.write(0);
        out.write(1);
        out.write(4);
        out.writeBytes(new byte[]{10, 0, 0, 1});
        out.writeBytes(new byte[]{0x27, 0x0f});

        try {
            PlanetFile.parse(out.toByteArray());
            fail("planet with an unsupported key layout accepted");
        } catch (PlanetFile.FormatException expected) {
            // expected
        }
    }

    @Test
    public void rejectsTooManyRoots() throws Exception {
        try {
            PlanetFile.parse(planet(1, 2, 9));
            fail("planet with too many roots accepted");
        } catch (PlanetFile.FormatException expected) {
            // expected
        }
    }
}
